        // the balance before the first withdrawal (because the withdrawAll removed
        // exactly the caller's credit, and the second deposit adds a positive amount).
        assert(balanceAfterSecondDeposit >= balanceBeforeWithdraw);
    }

    receive() external payable {}
}

