contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount) public payable {
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        // Setup: deposit into c under the caller's account.
        c.deposit{value: depositAmount}();

        // Read the observable before-values.
        uint creditBefore = c.credit(address(this));
        uint balanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;

        // Make the deciding call.
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }

        // Read the observable after-values.
        uint creditAfter = c.credit(address(this));
        uint balanceAfter = address(c).balance;
        uint selfBalanceAfter = address(this).balance;

        // General rule: success sends exactly the caller's credit to them and zeroes it;
        // revert leaves both credit and c's balance unchanged.
        if (!reverted) {
            assert(creditAfter == 0 &&
                   balanceAfter == balanceBefore - creditBefore &&
                   selfBalanceAfter == selfBalanceBefore + creditBefore);
        } else {
            assert(creditAfter == creditBefore && balanceAfter == balanceBefore);
        }
    }

    receive() external payable {}
}

